  "approved_angle": {
    "title": "Why Carmen wanted more time and another set of eyes on a venue campaign",
    "core_perspective": "We want enough evidence to make a useful recommendation. In office hours, Carmen considered how much traffic a venue campaign had received, looked at what visitors were doing after the click and recommended Jacqueline's feedback on the landing page. She kept the open questions open."
  },
  "sharpened_point": null,
  "strategic_purpose": {
    "pillar": "WARM",
    "content_type": "behind_the_scenes",
    "why_now": "Make expert support tangible through a specific judgment call: allowing more time while identifying something worth reviewing now. The piece builds trust in the team's guidance without an offer pitch or repeating the recent buying-research and pre-tour nurture arguments."
  },
  "audience": {
    "who": "Venue owners who already invest in marketing and want informed guidance as they grow their wedding and event business.",
    "reason_to_care": "They want to know, 'Should we change the campaign yet?' This shows how WIA turns that question into a useful next step, including when to keep gathering data and when to seek another specialist's perspective."
  },
  "intended_shift": {
    "understand": "Giving a campaign more time and reviewing its landing page can be complementary recommendations.",
    "believe": "Expert guidance includes deciding what deserves attention next, rather than rushing to a verdict.",
    "do": "Approach the next campaign review with questions about the available traffic, visitor behavior and where specialist feedback would help."
  },
  "point_of_view": "we",
  "wia_perspective": "We want our campaign reviews to leave an owner with a clear next step. We consider how much traffic there is to assess, look at what visitors do after the click and draw on the team's expertise when a page deserves a closer look. In office hours, Carmen, our Google Ads lead, recommended giving a venue's corporate-events campaign more time and asking Jacqueline for landing-page feedback. Those recommendations can sit alongside each other. We believe good marketing decisions start with good data, and a useful review helps us decide where to look next.",
  "supporting_example": {
    "scene": "During office hours, Carmen, our Google Ads lead, reviewed a venue's campaign for corporate events. She considered the traffic available and examined how visitors moved through the landing page.",
    "wia_move": "Carmen recommended allowing the campaign more time to develop and seeking landing-page feedback from Jacqueline, our Meta ads strategist. She gave the owner two directions for the review: continue gathering data and bring another specialist's perspective to the page.",
    "client_contribution": "The venue's corporate-events campaign and landing page gave the discussion a specific focus."
  },
  "narrative_outline": {
    "hooks": [
      {
        "style": "observation",
        "text": "Carmen's campaign review led to two recommendations that belonged together."
      },
      {
        "style": "question",
        "text": "How do we decide what deserves attention while a campaign is still gathering data?"
      },
      {
        "style": "contrarian_belief",
        "text": "A useful campaign review can give you a next step before it gives you a verdict."
      }
    ],
    "problems_desires_symptoms": [
      "The owner wants to decide whether to keep running the campaign or make a change.",
      "They value guidance that explains what to examine next.",
      "Keep the example explicitly about corporate events at a venue; connect the decision-making principle to wedding advertising."
    ],
    "main_point": "More time and a closer review can work together. Show Carmen assessing the available traffic, looking beyond the click and recommending Jacqueline's perspective.",
    "transformation": "Move from seeking an immediate verdict to understanding the next useful action and why it deserves attention.",
    "cta": "No explicit ask. End on the value of a clear next step."
  },
  "format_plan": {
    "reels": [
      {
        "job": "Show the paired recommendation through one office-hours scene. New talking-head recording, approximately 125 to 140 words.",
        "cover_text": "What we review before changing a campaign",
        "spoken_opening": "What makes a campaign review useful when you're still deciding what to change?",
        "beats": [
          "Introduce Carmen as our Google Ads lead and establish that the review concerned a venue's corporate-events campaign.",
          "Describe her assessment of the available traffic and her look at visitor behavior, without client metrics or individual visitor details.",
          "State that she recommended more time to assess the campaign.",
          "Add her recommendation to ask Jacqueline for landing-page feedback. Do not imply Jacqueline attended or completed the review.",
          "Close on the principle: continuing to gather data and taking a closer look can happen together. No CTA."
        ],
        "read_time_seconds": 60,
        "source": "new_script",
        "evidence_ids": [
          "ev_c021717b8b8e7d3ead3ed50d",
          "ev_537e72b4567eac710dcc48d9",
          "ev_99eeb361297e358ab40f614e",
          "ev_c72a21e1aadc0d3c02147548"
        ]
      }
    ],
    "carousel": {
      "job": "Give venue owners a substantive view of how WIA decides what to examine next. Seven slides, with the corporate-events scene anchoring the principle.",
      "slides": [
        {
          "number": 1,
          "job": "Introduce the paired decision and its relevance.",
          "text": "Giving a campaign more time can include taking a closer look.\n\nWhen you're deciding whether to make a change, there are two useful questions to hold together: what can we learn as more traffic comes through, and what deserves a review now?",
          "evidence_ids": [
            "ev_c021717b8b8e7d3ead3ed50d",
            "ev_c72a21e1aadc0d3c02147548"
          ]
        },
        {
          "number": 2,
          "job": "Establish the real scene without client performance details.",
          "text": "In office hours, our Google Ads lead, Carmen, was reviewing a venue's corporate-events campaign.\n\nShe considered how much traffic there was to assess and looked at visitors' movement through the landing page. Her review connected what was happening in the campaign with the experience after the click.",
          "evidence_ids": [
            "ev_241bad449451f64e3c2d1754",
            "ev_537e72b4567eac710dcc48d9",
            "ev_99eeb361297e358ab40f614e"
          ]
        },
        {
          "number": 3,
          "job": "Explain why the amount of available evidence matters.",
          "text": "Carmen wanted the campaign to have more breathing room before judging its success.\n\nThat's part of how we approach a review: we consider the amount of traffic behind the patterns we're examining. The next decision should reflect what there is to assess, as well as what we're trying to learn.",
          "evidence_ids": [
            "ev_c021717b8b8e7d3ead3ed50d",
            "ev_537e72b4567eac710dcc48d9"
          ]
        },
        {
          "number": 4,
          "job": "Show how visitor behavior guides the next question without assigning a cause.",
          "text": "Leaving a page quickly and spending time exploring it are different patterns.\n\nWe look at that behavior to guide the next question. Should we examine who the ad is reaching, or take a closer look at the page visitors arrive on? That gives the review a more specific direction.",
          "evidence_ids": [
            "ev_7b0270f6eeccf1a649374357",
            "ev_31df597cbe215f7ea38b07c1",
            "ev_28e788a39b4828bd4be71362",
            "ev_537e72b4567eac710dcc48d9"
          ]
        },
        {
          "number": 5,
          "job": "Make the team's collaborative contribution concrete.",
          "text": "The landing page was one place Carmen wanted another perspective.\n\nShe recommended asking Jacqueline, our Meta ads strategist, for feedback on the venue's corporate-events page. Bringing in a colleague's expertise is a practical way to examine the experience visitors have after an ad brings them to the business.",
          "evidence_ids": [
            "ev_e9cd1aa508843192e6f92f86",
            "ev_c78a9beda84e171c2eea9d56",
            "ev_c72a21e1aadc0d3c02147548"
          ]
        },
        {
          "number": 6,
          "job": "Resolve the apparent tension between waiting and reviewing.",
          "text": "These recommendations work alongside each other.\n\nLetting more traffic come through gives us more to assess. Seeking feedback gives us another perspective on the page. We can continue learning from the campaign while choosing a specific part of the experience to examine more closely.",
          "evidence_ids": [
            "ev_c021717b8b8e7d3ead3ed50d",
            "ev_c72a21e1aadc0d3c02147548",
            "ev_99eeb361297e358ab40f614e"
          ]
        },
        {
          "number": 7,
          "job": "Connect the corporate-events example to the reader's wedding advertising decisions.",
          "text": "The same questions belong in a review of your wedding advertising.\n\nHow much traffic are we assessing? What are visitors doing when they arrive? Where would another specialist's feedback help?\n\nThose questions give us a way to choose the next action with care, whether we're reviewing an ad or the page where couples inquire.",
          "evidence_ids": [
            "ev_c021717b8b8e7d3ead3ed50d",
            "ev_99eeb361297e358ab40f614e",
            "ev_c72a21e1aadc0d3c02147548"
          ]
        }
      ]
    },
    "email": {
      "subject_options": [
        "The recommendation Carmen made in office hours",
        "More time for the campaign, feedback for the page"
      ],
      "preview": "How our team decides what deserves a closer look.",
      "opening": "Hi {{contact.first_name}},\n\nIn an office-hours review, Carmen suggested bringing Jacqueline's perspective to a landing page. She also wanted to give the campaign more time to develop.\n\nThose two recommendations fit together, and they're a useful example of how we approach decisions about ads.",
      "argument": "Carmen is our Google Ads lead. In this conversation, she was reviewing a venue's campaign for corporate events, considering the traffic available and looking at how visitors moved through the page.\n\nShe wanted more breathing room to assess the campaign. At the same time, she recommended asking Jacqueline, our Meta ads strategist, for feedback on the corporate-events landing page.\n\nWhen we review a campaign, we consider both the amount of data we have and the questions it raises. Visitor behavior can help direct our attention toward the audience an ad is reaching or the experience people have when they arrive on the page.\n\nFrom there, we can identify something worth examining while the campaign continues gathering data. Another specialist's perspective can be part of that work.",
      "transformation": "For a venue owner, that gives the question 'Should we change anything yet?' a more useful shape.\n\nWe can consider what needs more time, what deserves a closer review and whose expertise would help. That approach applies when you're promoting corporate events, and when you're advertising to couples planning their wedding.",
      "ending": "A thoughtful review gives the next decision a direction. In this case, Carmen's guidance was to keep gathering evidence and seek another perspective on the page.\n\nThat's the kind of clarity we want our support to provide.\n\nTalk soon,\nWhitney",
      "evidence_ids": [
        "ev_241bad449451f64e3c2d1754",
        "ev_c021717b8b8e7d3ead3ed50d",
        "ev_537e72b4567eac710dcc48d9",
        "ev_7b0270f6eeccf1a649374357",
        "ev_31df597cbe215f7ea38b07c1",
        "ev_28e788a39b4828bd4be71362",
        "ev_c72a21e1aadc0d3c02147548",
        "ev_99eeb361297e358ab40f614e"
      ]
    },
    "caption": {
      "hook": "The next step in an ad account can start with a question about the page.",
      "adds": "When you're investing in advertising for your venue, you want to understand what deserves attention and what can keep developing. A campaign review should help you make that decision with a clear reason behind it.\n\nDuring office hours, Carmen, our Google Ads lead, considered those questions for a venue's corporate-events campaign. She looked at the traffic available and how visitors moved through the landing page. Alongside giving the campaign more time, she recommended asking Jacqueline for feedback on the page itself.\n\nThat combination matters. Continuing to gather data and seeking another perspective can be part of the same review.\n\nWe look at visitor behavior to help choose what to examine next. A quick departure from a page gives us a different question to explore than a visit where someone spends time looking around. From there, we can consider the audience the ad is reaching and the experience they're arriving to.\n\nFor wedding advertising, that means looking beyond the click at the page where couples decide whether to inquire.",
      "ending": "We want the owner to leave a review knowing what we'll examine next and why that step makes sense."
    },
    "stories": null
  },
